fs.writeFileSync('assets/core-product-reference.css',css);
function sectionHead(num,title,copy){return `<div class="reference-section-head"><span class="num">${num}</span><h2>${title}</h2>${copy?`<p>${copy}</p>`:''}</div>`}
function buildMain(p){
 const rows=p.rows.map(([k,v])=>`<tr><th scope="row">${k}</th><td>${v}</td></tr>`).join('');
 const fields=buyerFields.map((f,i)=>`<div class="buyer-field"><small>${String(i+1).padStart(2,'0')}</small><strong>${f}</strong></div>`).join('');
 const mail=`mailto:sales@uniqueholding.com.tr?subject=${encodeURIComponent(p.mail)}`;
 return `<main id="main"><div class="detail-shell" data-reference-detail="true"><nav class="detail-breadcrumb" aria-label="Breadcrumb"><a href="index.html">Unique Holding</a><span aria-hidden="true">/</span><a href="products.html">Industrial Products</a><span aria-hidden="true">/</span><span aria-current="page">${p.name}</span></nav><header class="reference-hero"><div class="reference-eyebrow"><p class="subsite-label">${p.family}</p><span class="reference-status">Reference detail</span></div><h1 class="detail-title">${p.name}</h1><div class="reference-identity-bar" aria-label="Reference identity"><div><small>Published product name</small><strong>${p.name}</strong></div><div><small>Approved identifier</small><strong>${p.abbr}</strong></div><div><small>Information status</small><strong>Published reference data</strong></div></div><p class="detail-lead">${p.lead}</p><div class="reference-hero-actions"><a class="button-link" href="products.html">Products index</a><a class="button-link primary" href="sales.html">Industrial Sales / RFQ</a></div></header>
<section class="reference-section" id="product-identity">${sectionHead('01 / Product Identity','Product identity','The page identifies only the approved name, family and identifier already present in the published reference route.')}<div class="reference-meta"><div><small>Product</small><strong>${p.name}</strong></div><div><small>Family</small><strong>${p.family}</strong></div><div><small>Identifier</small><strong>${p.abbr}</strong></div></div></section>
<section class="reference-section" id="commercial-route">${sectionHead('02 / Commercial Route / Variant Context',p.routeTitle,'Reference-detail status does not turn the wider catalog into published specification pages.')}<div class="reference-route-card"><h3>Reference page versus inquiry route</h3><div>${p.routeHtml}</div></div></section>
<section class="reference-section" id="published-reference">${sectionHead('03 / Published Reference Data','Reference specification','Every value below is preserved from the approved product page. No absent parameter has been added or normalized.')}<div class="reference-table-wrap" tabindex="0" role="region" aria-label="${p.name} published reference data"><table class="reference-table"><caption>Published reference data</caption><thead><tr><th scope="col">Parameter</th><th scope="col">Published reference value</th></tr></thead><tbody>${rows}</tbody></table></div></section>
<section class="reference-section" id="specification-boundary">${sectionHead('04 / Specification Interpretation / Boundary','Reference data is not the offered-lot guarantee','The technical block supports initial review while commercial confirmation remains transaction-specific.')}<aside class="reference-boundary" role="note"><strong>Evidence boundary</strong><p>Published values are reference technical information. Final specification, packing, availability and commercial terms are confirmed against the offered lot at the time of inquiry.</p></aside></section>
<section class="reference-section" id="buyer-requirement">${sectionHead('05 / Buyer Requirement','What Industrial Sales needs','Use the approved RFQ fields so technical review can move directly into commercial review without guessing the buyer requirement.')}<div class="buyer-field-grid">${fields}</div></section>
<section class="reference-section" id="commercial-review">${sectionHead('06 / Commercial Review / Industrial Sales','Proceed with the requirement','Producer, origin, packing, availability and final commercial terms are confirmed only for the offered lot and transaction.')}<div class="reference-commercial"><p>Send the requirement with the known buyer fields. The Sales route provides the structured RFQ workflow and direct industrial sales contact.</p><div class="detail-cta"><a class="button-link primary" href="${mail}">Email Industrial Sales</a><a class="button-link" href="sales.html">Open RFQ guide</a></div></div></section></div></main>`;
}
for(const [file,p] of Object.entries(pages)){
 let html=fs.readFileSync(file,'utf8');
 html=html.replace('<body class="subsite-body">','<body class="subsite-body reference-page">');
 if(!html.includes('assets/core-product-reference.css')) html=html.replace('<link rel="stylesheet" href="assets/internal.css">','<link rel="stylesheet" href="assets/internal.css"><link rel="stylesheet" href="assets/core-product-reference.css">');
 html=html.replace(/<main id="main"><div class="detail-shell">[\s\S]*?<\/div><\/main>/,buildMain(p));
 if(!html.includes('data-reference-detail="true"'))throw new Error(`main replacement failed: ${file}`);
 fs.writeFileSync(file,html);
}
let qa=fs.readFileSync('scripts/qa-site.mjs','utf8');
const guard=`\n// Phase 10 — authoritative core-product reference-page guards.\n{\n  const phase10Pages=${JSON.stringify(Object.fromEntries(Object.entries(pages).map(([f,p])=>[f,{name:p.name,values:p.rows.flat(),family:p.family}])))};\n  const claimBan=['in stock','available now','our factory','our plant','our production','our warehouse','our terminal','our fleet','direct producer','exclusive supplier','leading supplier','global supplier','certified supplier','guaranteed supply','annual capacity','minimum order','moq','immediate delivery'];\n  for(const [file,meta] of Object.entries(phase10Pages)){\n    const html=read(file);const lower=html.toLowerCase();\n    if(noindex(html))errors.push(\`${'${file}'}: Phase 10 reference route must remain indexable\`);\n    if((html.match(/<h1\\b/gi)||[]).length!==1)errors.push(\`${'${file}'}: Phase 10 reference route must have exactly one H1\`);\n    for(const token of ['assets/core-product-reference.css','data-reference-detail="true"','Reference detail','01 / Product Identity','02 / Commercial Route / Variant Context','03 / Published Reference Data','04 / Specification Interpretation / Boundary','05 / Buyer Requirement','06 / Commercial Review / Industrial Sales','<table class="reference-table">','<caption>Published reference data</caption>','scope="col"','scope="row"','products.html','sales.html','Product','Grade / specification','Quantity','Destination','Timing','Specification','Contact'])if(!html.includes(token))errors.push(\`${'${file}'}: Phase 10 authority architecture regression -> ${'${token}'}\`);\n    for(const value of meta.values)if(!html.includes(value))errors.push(\`${'${file}'}: approved Phase 10 technical value missing -> ${'${value}'}\`);\n    for(const phrase of claimBan)if(lower.includes(phrase))errors.push(\`${'${file}'}: unsupported Phase 10 product claim -> ${'${phrase}'}\`);\n    const canonical='https://www.uniqueholding.com.tr/'+file;if(!html.includes(\`rel="canonical" href="${'${canonical}'}"\`))errors.push(\`${'${file}'}: Phase 10 canonical regression\`);\n  }\n  const p09=read('products.html');\n  const refs=(p09.match(/data-destination="reference-detail"/g)||[]).length;const inquiries=(p09.match(/data-destination="inquiry-detail"/g)||[]).length;\n  if(refs!==3||inquiries!==62)errors.push(\`Phase 10: Phase 09 route classification regression REFERENCE=${'${refs}'} INQUIRY=${'${inquiries}'}\`);\n  for(const [slug,href] of [['urea-46','urea-46.html'],['caustic-soda-solid','caustic-soda-solid.html'],['sodium-sulphate-anhydrous','sodium-sulphate-anhydrous.html']])if(!p09.includes(\`data-slug="${'${slug}'}" href="${'${href}'}"\`))errors.push(\`Phase 10: Core route destination regression -> ${'${slug}'}\`);\n}\n`;
if(!qa.includes('// Phase 10 — authoritative core-product reference-page guards.'))qa+=guard;
fs.writeFileSync('scripts/qa-site.mjs',qa);
console.log('PHASE 10 BUILD COMPLETE');